-- District Software Inventory widget (Sean and Trisha, 2026-11-09). Same model as the
-- II&DL Services Directory: public read-only embed at /embeds/software-inventory.html,
-- edits through /api/bcps/software-inventory (service role, ACL-gated). Seeded from
-- forwebsite_9Nov2026.xlsx, Sheet1 (the Office of Academics master list). The second
-- tab (CTC export with staff contacts) is not loaded. Internal tracking columns
-- (agreement_vendor, contract_file_name, ctc_updated, ctc_rating, software_type,
-- usage_type) are NOT readable by anon (column-level grants below).

CREATE TABLE IF NOT EXISTS public.bcps_software_inventory (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  program_name text NOT NULL,
  vendor text,
  subject text,
  department text,
  grade_band text,
  intended_use text,
  description text,
  bid_id text,
  vendor_terms_label text,
  vendor_terms_url text,
  board_agreement_url text,
  agreement_vendor text,
  contract_file_name text,
  ctc_updated text,
  ctc_rating text,
  software_type text,
  usage_type text,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.bcps_software_inventory ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "public read software inventory" ON public.bcps_software_inventory;
CREATE POLICY "public read software inventory" ON public.bcps_software_inventory FOR SELECT TO anon, authenticated USING (true);
REVOKE ALL ON public.bcps_software_inventory FROM anon, authenticated;
GRANT SELECT (id, program_name, vendor, subject, department, grade_band, intended_use, description, bid_id,
  vendor_terms_label, vendor_terms_url, board_agreement_url, sort_order)
  ON public.bcps_software_inventory TO anon, authenticated;

